    import { mapState } from 'vuex';
	// import theme from "@/mixins/theme";
    export default {
        name: 'home_coupon',
        cname: '优惠券',
        configName: 'c_home_coupon',
        icon: '#iconzujian-youhuiquan',
        type:1,// 0 基础组件 1 营销组件 2工具组件
        defaultName:'coupon', // 外面匹配名称
        props: {
            index: {
                type: null
            },
            num: {
                type: null
            },
			colorStyle:{
				type: null
			}
        },
        computed: {
            ...mapState('admin/mobildConfig', ['defaultArray'])
        },
        watch: {
            pageData: {
                handler (nVal, oVal) {
                    this.setConfig(nVal)
                },
                deep: true
            },
            num: {
                handler (nVal, oVal) {
                    let data = this.$store.state.admin.mobildConfig.defaultArray[nVal]
                    this.setConfig(data)
                },
                deep: true
            },
            'defaultArray': {
                handler (nVal, oVal) {
                    let data = this.$store.state.admin.mobildConfig.defaultArray[this.num]
                    this.setConfig(data);
                },
                deep: true
            }
        },
        // mixins: [theme],
		data () {
            return {
                // 默认初始化数据禁止修改
                defaultConfig: {
					cname: '优惠券',
                    name: 'coupon',
                    timestamp: this.num,
					isHide:false,
					setUp: {
					  tabVal: 0
					},
					titleLeft:'展示设置',
					titleData:'优惠券数据',
					titleRight:'优惠券样式',
					titleCurrency:'通用样式',
					styleConfig:{
						title: '选择风格',
						tabVal:0,
						type:'coupon'
					},
					numberConfig:{
						title: '展示数量',
						val: 5,
						min: 1
					},
					toneConfig:{
						title: '色调',
						tabVal: 0,
						tabList: [
							{
							  name: '跟随主题风格'
							},
						    {
						      name: '自定义'
						    }
						]
					},
					couponMoneyColor:{
						title: '优惠金额',
						default: [
						    {
						        item: '#E93323'
						    }

						],
						color: [
						    {
						        item: '#E93323'
						    }

						]
					},
					bntBgColor:{
						title: '按钮背景',
						name: 'bntBgColor',
						default: [
						    {
						        item: '#FF7931'
						    },
							{
							    item: '#E93323'
							}
						],
						color: [
						    {
						        item: '#FF7931'
						    },
						    {
						        item: '#E93323'
						    }
						]
					},
					couponBgColor:{
						title: '优惠券背景',
						default: [
						    {
						        item: '#E93323'
						    }

						],
						color: [
						    {
						        item: '#E93323'
						    }

						]
					},
					spacingConfig:{
						title: '优惠券间距',
						val: 6,
						min: 0
					},
					moduleColor:{
						title: '组件背景',
						default: [
						    {
						        item: '#E93323'
						    },
							{
							    item: '#FF7931'
							}
						],
						color: [
						    {
						        item: '#E93323'
						    },
						    {
						        item: '#FF7931'
						    }
						]
					},
					moduleColor2:{
						title: '组件背景',
						default: [
						    {
						        item: '#ffffff'
						    }
						],
						color: [
						    {
						        item: '#ffffff'
						    }
						]
					},
					bottomBgColor:{
						title: '底部背景',
						default: [
						    {
						        item: '#f5f5f5'
						    }
						],
						color: [
						    {
						        item: '#f5f5f5'
						    }
						]
					},
					topConfig: {
						title: '上边距',
						val: 0,
						min: 0
					},
					bottomConfig: {
						title: '下边距',
						val: 0,
						min: 0
					},
					prConfig: {
					    title: '左右边距',
					    val: 10,
					    min: 0
					},
					mbConfig: {
					    title: '页面上间距',
					    val: 0,
					    min: 0
					},
					fillet:{
						title:'背景圆角',
						type: 0,
						list: [
						  {
						    val: "全部",
						    icon: "iconcaozuo-zhengti",
						  },
						  {
						    val: "单个",
						    icon: "iconcaozuo-bianjiao",
						  }
						],
						valName:'圆角值',
						val: 8,
						min: 0,
						valList:[
							{val:0},
							{val:0},
							{val:0},
							{val:0}
						]
					}
                },
                pageData: {},
				numberConfig:0,
				styleConfig:0,
				toneConfig:0,
				couponMoneyColor:'',
				bntBgColorLeft:'',
				bntBgColorRight:'',
				couponBgColor:'',
				spacingConfig:0,
				moduleColor:'',
				moduleColor2:'',
				topConfig:0,
				bottomConfig:0,
				prConfig:0,
				bgRadius:0,
                mTop: 0,
				bottomBgColor:'',
				themeColor:'',
				themeColor2:''
            }
        },
        mounted () {
            this.$nextTick(() => {
                this.pageData = this.$store.state.admin.mobildConfig.defaultArray[this.num]
                this.setConfig(this.pageData)
            })
        },
        methods: {
            setConfig (data) {
                if(!data) return
                if(data.mbConfig){
					this.numberConfig = data.numberConfig.val;
					this.styleConfig = data.styleConfig.tabVal;
					this.toneConfig = data.toneConfig.tabVal;
					this.couponMoneyColor = data.couponMoneyColor.color[0].item;
					this.bntBgColorLeft = data.bntBgColor.color[0].item;
					this.bntBgColorRight = data.bntBgColor.color[1].item;
					this.couponBgColor = data.couponBgColor.color[0].item;
					this.spacingConfig = data.spacingConfig.val;
					let moduleColorLeft = data.moduleColor.color[0].item;
					let moduleColorRight = data.moduleColor.color[1].item;
					this.moduleColor = `linear-gradient(90deg,${moduleColorLeft} 0%,${moduleColorRight} 100%)`
					this.moduleColor2 = data.moduleColor2.color[0].item;
					this.topConfig = data.topConfig.val;
					this.bottomConfig = data.bottomConfig.val;
					this.prConfig = data.prConfig.val;
					let fillet = data.fillet.type;
					let filletVal = data.fillet.val
					let valList = data.fillet.valList;
					this.bgRadius = fillet? valList[0].val+ 'px ' +valList[1].val + 'px '+valList[3].val + 'px '+valList[2].val +'px': filletVal +'px';
                    this.mTop = data.mbConfig.val;
					this.bottomBgColor = data.bottomBgColor.color[0].item;
					this.themeColor = `linear-gradient(90deg,${this.colorStyle.theme} 0%,${this.colorStyle.gradient} 100%)`;
					this.themeColor2 = `linear-gradient(0deg,${this.colorStyle.theme} 0%,${this.colorStyle.gradient} 100%)`;
                }
            }
        }
    }
